text:
다음 코드의 출력은?
int x = 5;
if (x >= 5) std::cout << "A";
else std::cout << "B";

다음 코드 실행 후 sum의 값은?
int sum = 0;
for (int i = 1; i <= 3; ++i) { sum += i; }

다음 while문의 본문은 몇 번 실행되는가?
int n = 0;
while (n < 3) { ++n; }

다음 코드 실행 후 x의 값은?
void change(int n) { n = 9; }
// main 내부
int x = 1;
change(x);

다음 코드 실행 후 x의 값은?
int x = 5;
int& ref = x;
ref = 8;

다음 코드 실행 후 x의 값은?
void increment(int& n) { ++n; }
// main 내부
int x = 4;
increment(x);

다음 코드 실행 후 x의 값은?
int x = 7;
int* p = &x;
*p = 12;

다음 객체 생성 후 c.value()의 반환값은?
class Counter {
    int count;
public:
    Counter(int n) : count(n) {}
    int value() const { return count; }
};
Counter c(7);

다음 코드에서 p->value()의 반환값은?
struct Base { virtual int value() const { return 1; } };
struct Derived : Base { int value() const override { return 2; } };
Derived d;
Base* p = &d;
